import{_ as a,o as t,c as i,ag as n}from"./chunks/framework.BwSLX4ak.js";const u=JSON.parse('{"title":"Upgrading and automatic updates","description":"","frontmatter":{},"headers":[],"relativePath":"en/shitbot/updating.md","filePath":"en/shitbot/updating.md"}'),s={name:"en/shitbot/updating.md"};function o(r,e,l,d,h,p){return t(),i("div",null,[...e[0]||(e[0]=[n(`<h1 id="upgrading-and-automatic-updates" tabindex="-1">Upgrading and automatic updates <a class="header-anchor" href="#upgrading-and-automatic-updates" aria-label="Permalink to &quot;Upgrading and automatic updates&quot;">​</a></h1><h2 id="before-upgrading" tabindex="-1">Before upgrading <a class="header-anchor" href="#before-upgrading" aria-label="Permalink to &quot;Before upgrading&quot;">​</a></h2><ol><li>Read the target version&#39;s <a href="https://github.com/hutuyee/ShitBot/releases" target="_blank" rel="noreferrer">release notes</a>.</li><li>Back up the database.</li><li>Back up <code>config.yml</code>, <code>commands.yml</code>, <code>lang/</code>, <code>templates/</code>, <code>image-templates/</code>, and custom image resources.</li><li>Check whether the proxy and backends must update together.</li><li>Do not directly copy SQLite while the server is running.</li></ol><p>If the proxy/backend protocol changes, update the proxy and all Spigot backends together. Mixed protocol versions may break commands, TPS queries, or coordinated updates.</p><p>Instances using advanced templates also need the matching ShitBotRenderer in the official release. After the platform plugin updates, the next startup checks the new component cache. The component downloads only when advanced templates are enabled.</p><h2 id="manual-upgrade" tabindex="-1">Manual upgrade <a class="header-anchor" href="#manual-upgrade" aria-label="Permalink to &quot;Manual upgrade&quot;">​</a></h2><ol><li>Stop the server or proxy.</li><li>Download the new JAR for your platform.</li><li>Move the old JAR out, leaving only one ShitBot platform JAR.</li><li>Put the new JAR in place.</li><li>Start and inspect configuration/database migration logs.</li><li>Review newly added fields saved automatically to configuration, language files, and image themes, and adjust as needed.</li><li>Run <code>/shitbot status</code>.</li><li>Verify OneBot, binding, forwarding, and shortcuts.</li></ol><p>Do not hot-unload the old JAR and hot-load the new one with a plugin manager.</p><p>Startup and reload save missing keys and <code>null</code> values in configuration, language files, and image themes while retaining existing values; see <a href="/docs/en/shitbot/configuration.html">Configuration</a>. When upgrading from <code>config-version: 1</code>, the first load imports replies, notices, built-in aliases/usage, and image titles from the old <code>config.yml</code> into <code>lang/zh_CN.yml</code> before completing the main configuration. Review the import before removing obsolete text settings yourself. Completion is recorded in <code>_migration.legacy-config-v1</code>, preventing repeated overwrites on reload.</p><h2 id="shitbot-update" tabindex="-1">/shitbot update <a class="header-anchor" href="#shitbot-update" aria-label="Permalink to &quot;/shitbot update&quot;">​</a></h2><p>Administrators with <code>shitbot.admin</code> can run:</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>/shitbot update</span></span></code></pre></div><p>The updater:</p><ol><li>Queries the latest GitHub release.</li><li>Selects the JAR for the current platform.</li><li>Downloads the JAR, <code>.sha256</code>, and <code>.sig</code>.</li><li>Verifies download addresses, size, and SHA-256.</li><li>Verifies the detached RSA signature with the embedded public key.</li><li>Checks the platform descriptor, main class, and embedded version.</li><li>Backs up the current JAR as <code>.bak</code> in the same directory.</li><li>Replaces the JAR and asks for a manual restart.</li></ol><p>This does not hot-reload the plugin. Restart the server or proxy normally afterward.</p><p>If any verification fails, the current JAR is retained. Do not bypass verification by removing <code>.sha256</code>, <code>.sig</code>, or altering release files.</p><h2 id="coordinated-network-updates" tabindex="-1">Coordinated network updates <a class="header-anchor" href="#coordinated-network-updates" aria-label="Permalink to &quot;Coordinated network updates&quot;">​</a></h2><p>Running <code>/shitbot update</code> on BungeeCord sends the same release&#39;s Spigot JAR and verification metadata to configured <code>backend-transport.endpoints</code>.</p><ul><li>Each backend verifies and replaces its own JAR independently.</li><li>The proxy reports each backend&#39;s result.</li><li>Backends without an endpoint are not scanned or updated.</li><li>You must still restart the proxy and backends manually.</li><li>Backend-mode Spigot does not independently check GitHub; the proxy handles notification and distribution.</li></ul><p>Before a coordinated update, confirm the channel works and back up databases and configurations on all instances.</p><h2 id="automatic-checks" tabindex="-1">Automatic checks <a class="header-anchor" href="#automatic-checks" aria-label="Permalink to &quot;Automatic checks&quot;">​</a></h2><p>After startup, the plugin checks GitHub releases in the background without occupying the server&#39;s main thread. Changed results are written to <code>update-cache.json</code> in the data directory.</p><p>Administrators with <code>shitbot.admin</code> receive an available-version notice and release link when joining. Automatic checks only notify; they do not replace the plugin without an update command.</p><h2 id="update-failures" tabindex="-1">Update failures <a class="header-anchor" href="#update-failures" aria-label="Permalink to &quot;Update failures&quot;">​</a></h2><p>Check that:</p><ul><li>The instance can reach <code>api.github.com</code> and GitHub release download hosts.</li><li>The release contains the current platform&#39;s JAR.</li><li>If advanced templates are enabled, the matching ShitBotRenderer is also present.</li><li>Matching <code>.jar.sha256</code> and <code>.jar.sig</code> files exist.</li><li>The JAR, checksum, and signature all come from the same release.</li><li>The plugin directory is writable.</li><li>The current JAR path can be identified and is not locked by another program.</li><li>The proxy/backend channel is healthy.</li></ul><p>If automatic updating fails, preserve the logs and use a manual upgrade, still downloading from the official release.</p><h2 id="release-maintainers-signing-keys" tabindex="-1">Release maintainers: signing keys <a class="header-anchor" href="#release-maintainers-signing-keys" aria-label="Permalink to &quot;Release maintainers: signing keys&quot;">​</a></h2><p>Server owners do not need to configure update keys. The public key is embedded in ShitBotCore. Store the private key only in the GitHub Actions <code>SHITBOT_UPDATE_PRIVATE_KEY</code> secret.</p><p>To generate or rotate a key:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">openssl</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> genpkey</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -algorithm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> RSA</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -pkeyopt</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> rsa_keygen_bits:3072</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -out</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> update-private-key.pem</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">openssl</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> pkey</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -in</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> update-private-key.pem</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -pubout</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -out</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> update-public-key.pem</span></span></code></pre></div><p>When rotating:</p><ol><li>Update ShitBotCore&#39;s embedded public key.</li><li>Update the private key in the repository secret.</li><li>Deploy the version containing the new public key through a trusted manual upgrade.</li><li>Sign subsequent releases with the new private key.</li></ol><p>Never commit the private key, bundle it in a JAR, or distribute it to server owners.</p>`,34)])])}const g=a(s,[["render",o]]);export{u as __pageData,g as default};
